// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        vm.prank(alice);
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.prank(alice);
        c.collectDrugs(bob);

        uint256 bobsClaimed = c.claimedDrugs(bob);
        assertTrue(bobsClaimed != 2592000, "Bob's claimed drugs should not equal 2592000");
    }
}
